package com.collegeerp.erp.academic.entity;
import com.collegeerp.erp.academic.enums.AttendanceSessionStatus; import com.collegeerp.erp.common.entity.BaseAuditEntity; import com.collegeerp.erp.staff.entity.StaffProfile; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="attendance_sessions",uniqueConstraints=@UniqueConstraint(columnNames={"section_id","subject_id","teacher_id","attendance_date"})) public class AttendanceSession extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="section_id") private Section section; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id") private Subject subject; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="teacher_id") private StaffProfile teacher; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="timetable_entry_id") private TimetableEntry timetableEntry; @Column(name="attendance_date") private LocalDate attendanceDate; private String topic; @Enumerated(EnumType.STRING) private AttendanceSessionStatus status=AttendanceSessionStatus.OPEN; public Long getId(){return id;} public Section getSection(){return section;} public void setSection(Section v){section=v;} public Subject getSubject(){return subject;} public void setSubject(Subject v){subject=v;} public StaffProfile getTeacher(){return teacher;} public void setTeacher(StaffProfile v){teacher=v;} public void setTimetableEntry(TimetableEntry v){timetableEntry=v;} public LocalDate getAttendanceDate(){return attendanceDate;} public void setAttendanceDate(LocalDate v){attendanceDate=v;} public String getTopic(){return topic;} public void setTopic(String v){topic=v;} public AttendanceSessionStatus getStatus(){return status;} public void setStatus(AttendanceSessionStatus v){status=v;} }
